<script setup>
import { ref, computed, onMounted } from 'vue';
import { Code2, LayoutDashboard, History, BookOpen, Sparkles, ChevronRight, Clock3, CircleCheck, ArrowRight, RotateCcw, Menu, X, ArrowLeft, Trophy, Zap } from 'lucide-vue-next';

const topics=ref([]), history=ref([]), selected=ref('javascript'), difficulty=ref('beginner'), count=ref(5), exercise=ref(null), answers=ref({}), result=ref(null), loading=ref(false), view=ref('home'), mobileMenu=ref(false), error=ref('');
const topicMeta={javascript:{tone:'gold',tag:'互動語言',badge:'JS'},html:{tone:'coral',tag:'標記語言',badge:'5'},css:{tone:'blue',tag:'樣式語言',badge:'✳'},java:{tone:'violet',tag:'物件導向',badge:'☕'},python:{tone:'green',tag:'簡潔易讀',badge:'Py'}};
const currentTopic=computed(()=>topics.value.find(t=>t.id===selected.value));
const scorePct=computed(()=>result.value?Math.round(result.value.score/result.value.total*100):0);
async function load(){try{const [t,h]=await Promise.all([fetch('/api/topics'),fetch('/api/attempts')]);if(!t.ok||!h.ok)throw Error('API');topics.value=await t.json();history.value=await h.json();}catch{error.value='無法連線至練習服務。請先啟動 Spring Boot API。';topics.value=[{id:'html',name:'HTML',icon:'⌘',description:'網頁內容與語意結構'},{id:'css',name:'CSS',icon:'◈',description:'樣式、版面與響應式設計'},{id:'javascript',name:'JavaScript',icon:'JS',description:'互動、語法與程式邏輯'},{id:'java',name:'Java',icon:'☕',description:'物件導向與核心語法'},{id:'python',name:'Python',icon:'Py',description:'簡潔語法與資料處理'}];}}
async function startPractice(){loading.value=true;error.value='';try{const r=await fetch('/api/exercises/generate',{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({topic:selected.value,difficulty:difficulty.value,count:count.value})});if(!r.ok)throw Error('產生題目失敗');exercise.value=await r.json();answers.value={};result.value=null;view.value='practice';window.scrollTo({top:0,behavior:'smooth'});}catch{error.value='題目載入失敗，請確認 API 已啟動。'}finally{loading.value=false;}}
async function submit(){if(!exercise.value)return;loading.value=true;try{const r=await fetch(`/api/exercises/${exercise.value.id}/submit`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({answers:exercise.value.questions.map(q=>({questionId:q.id,selectedOption:answers.value[q.id]??null}))})});if(!r.ok)throw Error();result.value=await r.json();exercise.value.questions=result.value.questions;view.value='result';await refreshHistory();}catch{error.value='送出答案失敗，請再試一次。'}finally{loading.value=false;}}
async function refreshHistory(){try{history.value=await(await fetch('/api/attempts')).json()}catch{}}
async function openAttempt(id){try{result.value=await(await fetch(`/api/attempts/${id}`)).json();exercise.value={id:result.value.exerciseId,topic:result.value.topic,questions:result.value.questions};view.value='result';}catch{}}
function goHome(){view.value='home';exercise.value=null;result.value=null;}
function formatDate(s){return new Date(s).toLocaleDateString('zh-TW',{month:'2-digit',day:'2-digit'})+' '+new Date(s).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit',hour12:false})}
onMounted(load);
</script>

<template>
  <div class="app-shell">
    <aside class="sidebar" :class="{'sidebar-open':mobileMenu}">
      <div class="brand"><div class="brand-mark"><Code2 :size="19"/></div><span>syntax<span class="brand-light">lab</span></span></div>
      <div class="side-label">學習空間</div>
      <button class="nav-link" :class="{active:view==='home'||view==='practice'||view==='result'}" @click="goHome"><LayoutDashboard :size="18"/>學習總覽</button>
      <button class="nav-link" :class="{active:view==='history'}" @click="view='history'"><History :size="18"/>練習紀錄<span class="nav-count">{{history.length}}</span></button>
      <div class="side-label topic-label">語法主題</div>
      <button v-for="t in topics" :key="t.id" class="topic-nav" :class="{'topic-selected':selected===t.id}" @click="selected=t.id;goHome()"><span class="topic-mini" :class="topicMeta[t.id]?.tone">{{topicMeta[t.id]?.badge||t.icon}}</span>{{t.name}}</button>
      <div class="side-bottom"><div class="streak-icon"><Zap :size="17"/></div><div><strong>每天進步一點</strong><small>持續練習，寫出好程式</small></div></div>
      <button class="close-menu" @click="mobileMenu=false"><X/></button>
    </aside>
    <main class="main-area">
      <header class="topbar"><button class="menu-button" @click="mobileMenu=!mobileMenu"><Menu/></button><div class="crumb">學習空間 <ChevronRight :size="14"/> <span>{{view==='history'?'練習紀錄':view==='practice'?'進行練習':view==='result'?'練習結果':'學習總覽'}}</span></div><div class="top-right"><span class="online-dot"></span>專注學習中</div></header>
      <div class="content">
        <div v-if="error" class="error-banner">{{error}}<button @click="error=''">×</button></div>
        <template v-if="view==='home'">
          <section class="welcome-row"><div><div class="eyebrow"><Sparkles :size="14"/> YOUR LEARNING SPACE</div><h1>今天想學點什麼？</h1><p class="welcome-sub">選擇一個主題，開始你的程式語法練習。</p></div><div class="welcome-art"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-code">&lt;/&gt;</div><span class="spark spark-a">✦</span><span class="spark spark-b">✳</span></div></section>
          <section class="stats-grid"><div class="stat-card"><div class="stat-icon purple"><BookOpen :size="19"/></div><div><small>練習主題</small><strong>{{topics.length}} <em>種語法</em></strong></div><span class="stat-foot">持續擴充中</span></div><div class="stat-card"><div class="stat-icon orange"><CircleCheck :size="19"/></div><div><small>完成練習</small><strong>{{history.length}} <em>次</em></strong></div><span class="stat-foot">每次練習都算數</span></div><div class="stat-card"><div class="stat-icon green"><Trophy :size="19"/></div><div><small>平均正確率</small><strong>{{history.length?Math.round(history.reduce((a,x)=>a+x.score/x.total,0)/history.length*100):0}}<em>%</em></strong></div><span class="stat-foot">一步一步更進步</span></div></section>
          <div class="section-heading"><div><span class="section-kicker">PICK YOUR PATH</span><h2>選擇練習主題</h2></div><span class="section-note">點選卡片開始練習 <ArrowRight :size="14"/></span></div>
          <section class="topic-grid"><button v-for="(t,i) in topics" :key="t.id" class="topic-card" :class="'card-'+(topicMeta[t.id]?.tone||'purple')" @click="selected=t.id"><div class="card-top"><div class="topic-icon" :class="topicMeta[t.id]?.tone">{{topicMeta[t.id]?.badge||t.icon}}</div><span class="topic-tag">{{topicMeta[t.id]?.tag||'核心語法'}}</span></div><h3>{{t.name}}</h3><p>{{t.description}}</p><div class="card-foot"><span>{{[12,18,24,14,16][i]}} 道題目</span><span class="card-arrow"><ArrowRight :size="16"/></span></div></button></section>
          <section class="start-panel"><div class="start-copy"><span class="section-kicker light-kicker">READY WHEN YOU ARE</span><h2>把學到的，變成你的。</h2><p>每次練習都會留下紀錄，隨時回來複習。</p></div><div class="start-controls"><label>難度<select v-model="difficulty"><option value="beginner">入門</option><option value="intermediate">進階</option><option value="advanced">挑戰</option></select></label><label>題數<select v-model.number="count"><option :value="3">3 題</option><option :value="5">5 題</option><option :value="10">10 題</option></select></label><button class="start-button" :disabled="loading" @click="startPractice"><Sparkles :size="17"/>{{loading?'準備中…':`開始 ${currentTopic?.name||'JavaScript'} 練習`}}<ArrowRight :size="17"/></button></div></section>
          <section class="recent-section"><div class="section-heading compact"><div><span class="section-kicker">PICK UP WHERE YOU LEFT OFF</span><h2>最近練習</h2></div><button class="text-link" @click="view='history'">查看全部 <ArrowRight :size="14"/></button></div><div v-if="history.length" class="history-list"> <button v-for="h in history.slice(0,3)" :key="h.id" class="history-row" @click="openAttempt(h.id)"><span class="history-topic" :class="topicMeta[h.topic]?.tone">{{topicMeta[h.topic]?.badge||h.topic}}</span><div class="history-main"><strong>{{h.topic.toUpperCase()}} 練習</strong><small><Clock3 :size="13"/>{{formatDate(h.completedAt)}}</small></div><span class="history-score" :class="h.score===h.total?'perfect':''">{{h.score}} / {{h.total}}</span><ChevronRight :size="17" class="history-chevron"/></button></div><div v-else class="empty-state"><div class="empty-icon"><BookOpen/></div><strong>還沒有練習紀錄</strong><span>選擇一個主題，開始第一回合吧！</span></div></section>
        </template>
        <template v-else-if="view==='practice'&&exercise">
          <button class="back-link" @click="goHome"><ArrowLeft :size="16"/>返回總覽</button><div class="practice-head"><div><div class="eyebrow"><span class="online-dot"></span> PRACTICE SESSION</div><h1>{{exercise.topic.toUpperCase()}} 語法練習</h1><p>選出你認為正確的答案，完成後即可查看詳解。</p></div><div class="question-count">{{exercise.questions.length}} <small>道題目</small></div></div>
          <div class="progress-track"><div :style="{width:(Object.keys(answers).length/exercise.questions.length*100)+'%'}"></div></div><section class="question-list"><article v-for="(q,i) in exercise.questions" :key="q.id" class="question-card"><div class="question-meta"><span class="q-number">{{String(i+1).padStart(2,'0')}}</span><span>QUESTION {{String(i+1).padStart(2,'0')}}</span></div><h3>{{q.prompt}}</h3><pre v-if="q.code" class="code-block"><code>{{q.code}}</code></pre><div class="options"><button v-for="(opt,j) in q.options" :key="j" class="option" :class="{chosen:answers[q.id]===j}" @click="answers[q.id]=j"><span class="option-letter">{{String.fromCharCode(65+j)}}</span><span>{{opt}}</span><span class="radio"></span></button></div></article></section><div class="submit-bar"><span>{{Object.keys(answers).length}} / {{exercise.questions.length}} 題已作答</span><button class="primary-button" :disabled="loading" @click="submit">{{loading?'批改中…':'提交答案'}}<ArrowRight :size="17"/></button></div>
        </template>
        <template v-else-if="view==='result'&&result">
          <button class="back-link" @click="goHome"><ArrowLeft :size="16"/>返回總覽</button><section class="result-hero"><div class="score-ring" :style="{'--score':scorePct+'%'}"><div><strong>{{scorePct}}</strong><span>分</span></div></div><span class="section-kicker">SESSION COMPLETE</span><h1>{{scorePct>=80?'做得非常好！':scorePct>=60?'持續進步中！':'再練一次會更好！'}}</h1><p>你答對 {{result.score}} 題，共 {{result.total}} 題。每次練習都讓你更進一步。</p><button class="primary-button" @click="startPractice"><RotateCcw :size="16"/>再練一次</button></section><div class="section-heading compact"><div><span class="section-kicker">ANSWER REVIEW</span><h2>答案詳解</h2></div></div><section class="question-list"><article v-for="(q,i) in result.questions" :key="q.id" class="question-card review-card"><div class="question-meta"><span class="q-number" :class="q.selectedOption===q.correctOption?'correct':'incorrect'">{{q.selectedOption===q.correctOption?'✓':'×'}}</span><span>QUESTION {{String(i+1).padStart(2,'0')}}</span></div><h3>{{q.prompt}}</h3><pre v-if="q.code" class="code-block"><code>{{q.code}}</code></pre><div class="options"><div v-for="(opt,j) in q.options" :key="j" class="option review-option" :class="{'correct-option':j===q.correctOption,'wrong-option':j===q.selectedOption&&j!==q.correctOption}"><span class="option-letter">{{String.fromCharCode(65+j)}}</span><span>{{opt}}</span><CircleCheck v-if="j===q.correctOption" :size="17"/><X v-else-if="j===q.selectedOption" :size="17"/></div></div><div class="explanation"><Sparkles :size="15"/><span>{{q.explanation}}</span></div></article></section>
        </template>
        <template v-else-if="view==='history'"><div class="eyebrow"><span class="online-dot"></span> YOUR PROGRESS</div><h1 class="page-title">練習紀錄</h1><p class="welcome-sub history-sub">每一次練習，都是進步的軌跡。</p><div v-if="history.length" class="history-list full-history"><button v-for="h in history" :key="h.id" class="history-row" @click="openAttempt(h.id)"><span class="history-topic" :class="topicMeta[h.topic]?.tone">{{topicMeta[h.topic]?.badge||h.topic}}</span><div class="history-main"><strong>{{h.topic.toUpperCase()}} 練習</strong><small><Clock3 :size="13"/>{{formatDate(h.completedAt)}}</small></div><span class="history-score" :class="h.score===h.total?'perfect':''">{{h.score}} / {{h.total}}</span><span class="score-percent">{{Math.round(h.score/h.total*100)}}%</span><ChevronRight :size="17" class="history-chevron"/></button></div><div v-else class="empty-state large-empty"><div class="empty-icon"><History/></div><strong>還沒有練習紀錄</strong><span>完成一回合練習後，紀錄就會出現在這裡。</span><button class="primary-button" @click="goHome">開始練習 <ArrowRight :size="16"/></button></div></template>
      </div>
      <footer class="footer"><span>© 2026 SyntaxLab</span><span>Learn a little. Code a lot.</span></footer>
    </main><div v-if="mobileMenu" class="mobile-scrim" @click="mobileMenu=false"></div>
  </div>
</template>
